const basic = $input.first().json;
const body = $('Webhook').first().json.body;

function stripBase64Prefix(base64String) {
  if (!base64String) return null;

  // Example input:
  // data:image/png;base64,iVBORw0KGgo...
  // data:audio/webm;base64,GkXfo59...
  if (base64String.includes(',')) {
    return base64String.split(',')[1];
  }

  return base64String;
}

return [
  {
    json: {
      // Basic feedback data
      event_type: basic.event_type,
      project_id: basic.project_id,
      video_id: basic.video_id,
      feedback_item_id: basic.feedback_item_id,
      timestamp_seconds: basic.timestamp_seconds,
      timestamp_label: basic.timestamp_label,
      written_comment: basic.written_comment,

      // Boolean checks
      has_screenshot: basic.has_screenshot,
      has_annotated_image: basic.has_annotated_image,
      has_voice_note: basic.has_voice_note,
      has_drawing: basic.has_drawing,

      // Screenshot image
      screenshot_file_name: body.screenshot_image?.file_name || null,
      screenshot_mime_type: body.screenshot_image?.mime_type || null,
      screenshot_base64_clean: stripBase64Prefix(body.screenshot_image?.base64),

      // Annotated image
      annotated_file_name: body.annotated_image?.file_name || null,
      annotated_mime_type: body.annotated_image?.mime_type || null,
      annotated_base64_clean: stripBase64Prefix(body.annotated_image?.base64),

      // Voice note
      voice_file_name: body.voice_note?.file_name || null,
      voice_mime_type: body.voice_note?.mime_type || null,
      voice_base64_clean: stripBase64Prefix(body.voice_note?.base64),

      // Drawing info
      drawing_tool: body.drawing_data?.tool || null,
      drawing_color: body.drawing_data?.color || null,

      // Other useful data
      created_at: body.created_at || null,
      source: body.source || null
    }
  }
];

const item = $input.first().json;

const output = {
  json: {
    event_type: item.event_type,
    project_id: item.project_id,
    video_id: item.video_id,
    feedback_item_id: item.feedback_item_id,
    timestamp_seconds: item.timestamp_seconds,
    timestamp_label: item.timestamp_label,
    written_comment: item.written_comment,
    has_screenshot: item.has_screenshot,
    has_annotated_image: item.has_annotated_image,
    has_voice_note: item.has_voice_note,
    has_drawing: item.has_drawing,
    screenshot_file_name: item.screenshot_file_name,
    annotated_file_name: item.annotated_file_name,
    voice_file_name: item.voice_file_name
  },
  binary: {}
};

if (item.screenshot_base64_clean) {
  const screenshotBuffer = Buffer.from(item.screenshot_base64_clean, 'base64');

  output.binary.screenshot = await this.helpers.prepareBinaryData(
    screenshotBuffer,
    item.screenshot_file_name || 'screenshot.png',
    item.screenshot_mime_type || 'image/png'
  );
}

if (item.annotated_base64_clean) {
  const annotatedBuffer = Buffer.from(item.annotated_base64_clean, 'base64');

  output.binary.annotated_image = await this.helpers.prepareBinaryData(
    annotatedBuffer,
    item.annotated_file_name || 'annotation.png',
    item.annotated_mime_type || 'image/png'
  );
}

if (item.voice_base64_clean) {
  const voiceBuffer = Buffer.from(item.voice_base64_clean, 'base64');

  output.binary.voice_note = await this.helpers.prepareBinaryData(
    voiceBuffer,
    item.voice_file_name || 'voice.webm',
    item.voice_mime_type || 'audio/webm'
  );
}

return [output];

